function Open-PretrustHeldScript([string]$Path,[string]$Sha256,[string]$Reason){if(-not[IO.Path]::IsPathRooted($Path)){throw$Reason};$full=[IO.Path]::GetFullPath($Path);$resolved=(Resolve-Path -LiteralPath $Path).Path;if($full-cne$resolved){throw$Reason};$item=Get-Item -LiteralPath $resolved -Force;$trustRoot=[IO.Path]::GetDirectoryName($PSScriptRoot);$chain=$item;while(($null -ne $chain) -and (($chain.FullName -ieq $trustRoot) -or ($chain.FullName.StartsWith(($trustRoot+[IO.Path]::DirectorySeparatorChar),[StringComparison]::OrdinalIgnoreCase)))){if($chain.Attributes-band[IO.FileAttributes]::ReparsePoint){throw$Reason};$acl=Get-Acl -LiteralPath $chain.FullName;if(-not$acl.AreAccessRulesProtected){throw$Reason};$chain=if($chain-is[IO.DirectoryInfo]){$chain.Parent}else{$chain.Directory}};$stream=[IO.File]::Open($resolved,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$memory=[IO.MemoryStream]::new();$stream.CopyTo($memory);$bytes=$memory.ToArray();$hash=[Security.Cryptography.SHA256]::Create();try{$actual=([BitConverter]::ToString($hash.ComputeHash($bytes)).Replace('-','').ToLowerInvariant())}finally{$hash.Dispose()};if($actual-cne$Sha256){$stream.Dispose();throw$Reason};$tokens=$null;$errors=$null;$text=[Text.UTF8Encoding]::new($false,$true).GetString($bytes);$ast=[Management.Automation.Language.Parser]::ParseInput($text,[ref]$tokens,[ref]$errors);if($errors.Count){$stream.Dispose();throw$Reason};$offset=if($null-ne$ast.ParamBlock){$ast.ParamBlock.Extent.EndOffset}else{0};$root=[IO.Path]::GetDirectoryName($resolved).Replace("'","''");$self=$resolved.Replace("'","''");$script=$text.Insert($offset,";`$PSScriptRoot='$root';`$PSCommandPath='$self';");return[pscustomobject]@{Bytes=$bytes;Created=$item.CreationTimeUtc;Length=$item.Length;Path=$resolved;Script=[ScriptBlock]::Create($script);Stream=$stream}}
function Close-PretrustHeldScript($Held,[string]$Reason){try{$item=Get-Item -LiteralPath $Held.Path -Force;if($item.CreationTimeUtc-ne$Held.Created-or$item.Length-ne$Held.Length){throw$Reason};$Held.Stream.Position=0;$memory=[IO.MemoryStream]::new();$Held.Stream.CopyTo($memory);$hash=[Security.Cryptography.SHA256]::Create();try{if(([BitConverter]::ToString($hash.ComputeHash($memory.ToArray())).Replace('-','').ToLowerInvariant())-cne([BitConverter]::ToString($hash.ComputeHash($Held.Bytes)).Replace('-','').ToLowerInvariant())){throw$Reason}}finally{$hash.Dispose()}}finally{$Held.Stream.Dispose()}}$bootstrap=Join-Path $PSScriptRoot 'OPERATOR_BOOTSTRAP.ps1';if(-not('PhaseBV3AncestorNative'-as[type])){Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class PhaseBV3AncestorNative {
