function Open-PhaseBV3AncestorChain([string]$Path,[string]$Reason){$full=[IO.Path]::GetFullPath($Path);$root=[IO.Path]::GetPathRoot($full);$targets=[Collections.Generic.List[string]]::new();$targets.Add($root);$cursor=$root;$relative=$full.Substring($root.Length);foreach($part in $relative.Split([IO.Path]::DirectorySeparatorChar,[StringSplitOptions]::RemoveEmptyEntries)){$cursor=Join-Path $cursor $part;$targets.Add($cursor)};$result=[Collections.Generic.List[Microsoft.Win32.SafeHandles.SafeFileHandle]]::new();try{foreach($target in $targets){$item=Get-Item -LiteralPath $target -Force -ErrorAction Stop;if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw$Reason};$raw=[PhaseBV3AncestorNative]::CreateFileW($target,0x00100080,3,[IntPtr]::Zero,3,0x02000000,[IntPtr]::Zero);if($raw-eq[System.IntPtr]::new(-1)){$error=[Runtime.InteropServices.Marshal]::GetLastWin32Error();if($error-eq5){$raw=[PhaseBV3AncestorNative]::CreateFileW($target,0,3,[IntPtr]::Zero,3,0x02000000,[IntPtr]::Zero)};if($raw-eq[System.IntPtr]::new(-1)){throw$Reason}};$result.Add([Microsoft.Win32.SafeHandles.SafeFileHandle]::new($raw,$true))};return,$result.ToArray()}catch{foreach($handle in $result){$handle.Dispose()};throw}}
function Open-PhaseBV3BootstrapHeld([string]$Path,[string]$Sha256,[string]$Reason,[bool]$RequireHash=$true){if(-not[IO.Path]::IsPathRooted($Path)){throw $Reason};$full=[IO.Path]::GetFullPath($Path);$resolved=(Resolve-Path -LiteralPath $Path).Path;if($full-cne$resolved){throw $Reason};$item=Get-Item -LiteralPath $resolved -Force;if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw $Reason};$stream=[IO.File]::Open($resolved,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$memory=[IO.MemoryStream]::new();$stream.CopyTo($memory);$bytes=$memory.ToArray();$memory.Dispose();$stream.Position=0;$hash=[Security.Cryptography.SHA256]::Create();try{$actual=([BitConverter]::ToString($hash.ComputeHash($bytes)).Replace('-','').ToLowerInvariant())}finally{$hash.Dispose()};if($RequireHash-and$actual-cne$Sha256){throw $Reason};return[pscustomobject]@{Bytes=$bytes;Path=$resolved;Sha256=$actual;Stream=$stream}}catch{$stream.Dispose();throw}}
$bootstrapHolds=[Collections.Generic.List[object]]::new();$bootstrapAncestorHolds=[Collections.Generic.List[object]]::new();try{foreach($dependency in @($PythonPath,$V3CorePath,$PhaseBSshKeygenPath,$PhaseBPublicKeyPath,$PhaseBMaterializedLoaderJson)){foreach($ancestor in @(Open-PhaseBV3AncestorChain ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($dependency))) 'PHASE_B_BOOTSTRAP_ANCESTOR_INVALID')){$bootstrapAncestorHolds.Add($ancestor)}}$pythonBootstrap=Open-PhaseBV3BootstrapHeld $PythonPath $PythonSha256 'PHASE_B_BOOTSTRAP_PYTHON_INVALID' $true;$bootstrapHolds.Add($pythonBootstrap);$v3Bootstrap=Open-PhaseBV3BootstrapHeld $V3CorePath $V3CoreSha256 'PHASE_B_BOOTSTRAP_V3_INVALID' $true;$bootstrapHolds.Add($v3Bootstrap);$sshBootstrap=Open-PhaseBV3BootstrapHeld $PhaseBSshKeygenPath $PhaseBSshKeygenSha256 'PHASE_B_BOOTSTRAP_SSH_INVALID' $true;$bootstrapHolds.Add($sshBootstrap);$publicBootstrap=Open-PhaseBV3BootstrapHeld $PhaseBPublicKeyPath $PhaseBPublicKeySha256 'PHASE_B_BOOTSTRAP_PUBLIC_KEY_INVALID' $true;$bootstrapHolds.Add($publicBootstrap);$materializedHold=Open-PhaseBV3BootstrapHeld $PhaseBMaterializedLoaderJson $null 'PHASE_B_BOOTSTRAP_MATERIALIZED_INVALID' $false;$bootstrapHolds.Add($materializedHold);$v3Encoded=[Convert]::ToBase64String($v3Bootstrap.Bytes);$v3Runner="import base64,sys;src=base64.b64decode('$v3Encoded');sys.argv=[sys.argv[1]]+sys.argv[2:];g={'__name__':'__main__','__file__':sys.argv[0]};exec(compile(src,sys.argv[0],'exec'),g,g)";& $pythonBootstrap.Path -I -B -c $v3Runner $V3CorePath verify-materialized --precommit $PrecommitRoot --materialized $materializedHold.Path --public-key $publicBootstrap.Path --signer-identity $PhaseBSignerIdentity --ssh-keygen $sshBootstrap.Path --expected-role 'putra-producer' --expected-release-root ([IO.Path]::GetDirectoryName($PSScriptRoot));if($LASTEXITCODE-ne0){throw 'PHASE_B_V3_CRYPTOGRAPHIC_PREINSTALL_VERIFY_FAILED'};$materializedText=[Text.UTF8Encoding]::new($false,$true).GetString($materializedHold.Bytes);$materialized=$materializedText|ConvertFrom-Json;if($materialized.schema_version-cne'finex-phase-b-materialized-loader-v3'-or$materialized.encoded_command-cne$PhaseBEncodedCommand-or$materialized.encoded_command_sha256-cne$PhaseBEncodedCommandSha256){throw 'PHASE_B_V3_MATERIALIZED_COMMAND_INVALID'};$loaderBindings=$materialized.decoded_bindings;$i=$loaderBindings.runtime_invocation;if([IO.Path]::GetFullPath($V3CorePath)-cne[IO.Path]::GetFullPath([string]$i.v3_core_path)-or$v3Bootstrap.Sha256-cne[string]$i.v3_core_sha256-or[IO.Path]::GetFullPath($PythonPath)-cne[IO.Path]::GetFullPath([string]$i.python_path)-or$PythonSha256-cne[string]$i.python_sha256-or[IO.Path]::GetFullPath($PhaseBSshKeygenPath)-cne[IO.Path]::GetFullPath([string]$i.ssh_keygen_path)-or$PhaseBSshKeygenSha256-cne[string]$i.ssh_keygen_sha256-or[IO.Path]::GetFullPath($PhaseBPublicKeyPath)-cne[IO.Path]::GetFullPath([string]$i.public_key_path)-or$PhaseBPublicKeySha256-cne[string]$i.public_key_file_sha256-or$PhaseBSignerIdentity-cne[string]$i.signer_identity){throw 'PHASE_B_V3_BOOTSTRAP_BINDING_INVALID'}}finally{foreach($held in $bootstrapHolds){$held.Stream.Dispose()};foreach($ancestor in $bootstrapAncestorHolds){$ancestor.Dispose()}}
$bootstrap=Join-Path $PSScriptRoot 'OPERATOR_BOOTSTRAP.ps1';$heldBootstrap=Open-PretrustHeldScript $bootstrap $BootstrapSha256 'BOOTSTRAP_IDENTITY_MISMATCH';. $heldBootstrap.Script;Close-PretrustHeldScript $heldBootstrap 'BOOTSTRAP_POST_IDENTITY_MISMATCH';$phaseB=Join-Path $PSScriptRoot 'OPERATOR_PHASE_B.ps1';if((Get-OperatorTextSha256 $PhaseBEncodedCommand)-cne$PhaseBEncodedCommandSha256){throw 'PHASE_B_ENCODED_COMMAND_MISMATCH'};$heldObserver=Open-PretrustHeldScript $loaderBindings.runtime_invocation.observer_path $loaderBindings.runtime_invocation.observer_sha256 'WINDOWS_OBSERVER_IDENTITY_MISMATCH';. $heldObserver.Script;Close-PretrustHeldScript $heldObserver 'WINDOWS_OBSERVER_POST_IDENTITY_MISMATCH';if($loaderBindings.future_pointer_path-cne[IO.Path]::GetFullPath($PhaseBCurrentPointer)-or$loaderBindings.future_pointer_sha256-cne$PhaseBCurrentPointerSha256){throw 'PHASE_B_V3_POINTER_BINDING_MISMATCH'};if(Test-Path -LiteralPath $PhaseBCurrentPointer){throw 'PHASE_B_POINTER_PREMATURE'};Assert-OperatorRestrictedAcl ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($PhaseBCurrentPointer)));Assert-OperatorPowerShellProcess $PowerShellPath $PowerShellSha256|Out-Null;$null=Assert-OperatorPinnedFile $PSCommandPath $SelfSha256 'SELF_IDENTITY_MISMATCH'
